async function retry(fn, n) {
  for (let i = 0; i < n; i++) {
    try { return await fn(); }
    catch (e) { if (i === n - 1) throw e; }
  }
}
let c = 0;
retry(async () => { c++; if (c < 3) throw 'err'; return 'ok'; }, 3)
  .then(r => console.log(r));
